style.css:
/* After the Rain — Roblox */

:root {
  /* swap these colors if you want */
  --my-bg: #e9e9e7;
  --my-surface: #f5f5f3;
  --my-text: #292929;
  --my-muted: #858585;
  --my-accent: #626262;
  --my-border: #d0d0ce;
}

/* soft monochrome background */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Georgia", serif !important;
}

/* muted links */
a {
  color: var(--my-accent) !important;
}

/* understated buttons */
button {
  border-radius: 3px !important;
  filter: grayscale(1) !important;
}

/* grayscale imagery */
img {
  filter: grayscale(100%) !important;
}

/* subtle borders */
hr {
  border-color: var(--my-border) !important;
}
